// Config and the reporting window.
const N8N_URL = 'http://localhost:5678';
const SUPABASE_URL = '';          // TODO: https://<project>.supabase.co
const ALERT_CHAT_ID = '';         // TODO: the Telegram chat that receives the report
const TIMEZONE = 'Europe/Madrid';
const REPORT_LANGUAGE = 'Russian';
const SUMMARY_MODEL = 'claude-haiku-4-5';
const ERROR_RATE_FLAG = 0.2;      // flag above 20% of runs failing
const SLOWDOWN_FACTOR = 2;        // flag when the median at least doubled
const SLOWDOWN_MIN_MS = 1000;     // ...and grew by at least a second
const PAGE_LIMIT = 250;
const MAX_PAGES = 40;             // 10,000 executions a week before the report says it is partial

if (!SUPABASE_URL) throw new Error('SUPABASE_URL is not configured in "Prepare"');
if (!ALERT_CHAT_ID) throw new Error('ALERT_CHAT_ID is not configured in "Prepare"');

const api = N8N_URL.replace(/\/+$/, '') + '/api/v1';
const sb = SUPABASE_URL.replace(/\/+$/, '') + '/rest/v1';
const until = DateTime.now().setZone(TIMEZONE);
const since = until.minus({ days: 7 });
// The snapshot key is the Monday of the week the report runs in. Re-running the report in
// the same week overwrites that week's row instead of adding a second one.
const weekStart = until.startOf('week').toISODate();

return [{
  json: {
    timezone: TIMEZONE,
    chatId: ALERT_CHAT_ID,
    language: REPORT_LANGUAGE,
    model: SUMMARY_MODEL,
    errorRateFlag: ERROR_RATE_FLAG,
    slowdownFactor: SLOWDOWN_FACTOR,
    slowdownMinMs: SLOWDOWN_MIN_MS,
    pageLimit: PAGE_LIMIT,
    maxPages: MAX_PAGES,
    since: since.toISO(),
    until: until.toISO(),
    weekStart,
    workflowsUrl: api + '/workflows?limit=' + PAGE_LIMIT + '&excludePinnedData=true',
    executionsUrl: api + '/executions?limit=' + PAGE_LIMIT + '&includeData=false',
    // Strictly earlier than this week, so a re-run compares with last week and not with
    // the snapshot it wrote an hour ago.
    prevSnapshotUrl: sb + '/health_snapshots?select=week_start,stats&week_start=lt.' + weekStart
      + '&order=week_start.desc&limit=1',
    snapshotUrl: sb + '/health_snapshots',
  },
}];

// Turns a week of executions into one line of numbers per workflow, and the flags.
const state = $('Prepare').first().json;
const since = Date.parse(state.since);
const until = Date.parse(state.until);

const listRes = $('List workflows').first().json || {};
const listBody = Array.isArray(listRes.data) ? listRes : (listRes.body || listRes);
const workflows = Array.isArray(listBody.data) ? listBody.data : [];
const listTruncated = !!listBody.nextCursor;

// Each page of executions arrives as one item holding a data array. Loose executions are
// accepted too, so the node does not depend on how n8n chose to split the response.
const execs = [];
let pages = 0;
let lastPageHadMore = false;
for (const item of $('Read executions').all()) {
  const b = item.json || {};
  if (Array.isArray(b.data)) {
    pages += 1;
    execs.push(...b.data);
    lastPageHadMore = !!b.nextCursor;
  } else if (b.workflowId !== undefined && b.startedAt !== undefined) {
    execs.push(b);
  }
}
const oldestSeen = execs.reduce((m, e) => Math.min(m, Date.parse(e.startedAt) || Infinity), Infinity);
// Stopped by the page cap while still inside the week: the numbers below are a subset,
// and the report has to say so rather than present them as the whole week.
const executionsTruncated = pages >= state.maxPages && lastPageHadMore && oldestSeen >= since;

let prevStats = {};
let prevWeek = null;
try {
  const r = $('Read last snapshot').first().json || {};
  const rows = Array.isArray(r.body) ? r.body : Array.isArray(r) ? r : [];
  if (rows[0] && rows[0].stats && typeof rows[0].stats === 'object') {
    prevStats = rows[0].stats;
    prevWeek = rows[0].week_start || null;
  }
} catch (e) {
  // No snapshot read at all is the same as the first week: nothing to compare with.
}

const ERROR = new Set(['error', 'crashed']);
const statusOf = (e) => e.status || (e.finished ? 'success' : (e.stoppedAt ? 'error' : 'running'));

const median = (xs) => {
  if (!xs.length) return null;
  const s = [...xs].sort((a, b) => a - b);
  const m = Math.floor(s.length / 2);
  return s.length % 2 ? s[m] : Math.round((s[m - 1] + s[m]) / 2);
};

const byId = new Map();
const names = new Map(workflows.map((w) => [String(w.id), w.name]));
const active = new Map(workflows.map((w) => [String(w.id), !!w.active]));
const bucket = (id) => {
  if (!byId.has(id)) byId.set(id, { runs: 0, errors: 0, canceled: 0, durations: [], lastSuccessAt: null });
  return byId.get(id);
};

for (const e of execs) {
  const t = Date.parse(e.startedAt);
  if (!Number.isFinite(t) || t < since || t >= until) continue;
  const id = String(e.workflowId);
  const b = bucket(id);
  const status = statusOf(e);
  b.runs += 1;
  if (ERROR.has(status)) b.errors += 1;
  if (status === 'canceled') b.canceled += 1;
  const end = Date.parse(e.stoppedAt);
  if (Number.isFinite(end) && end >= t && status !== 'running' && status !== 'waiting') {
    b.durations.push(end - t);
  }
  if (status === 'success' && Number.isFinite(end)) {
    if (!b.lastSuccessAt || end > Date.parse(b.lastSuccessAt)) b.lastSuccessAt = new Date(end).toISOString();
  }
}

// Every active workflow gets a row even with zero runs: silence is exactly what this
// report exists to catch. Inactive workflows are counted, not flagged - they are not
// supposed to run, and flagging them every week would teach you to skip the report.
for (const w of workflows) if (w.active) bucket(String(w.id));

const rows = [];
for (const [id, b] of byId) {
  const p50 = median(b.durations);
  const prev = prevStats[id] || null;
  const prevP50 = prev && Number.isFinite(Number(prev.p50Ms)) ? Number(prev.p50Ms) : null;
  const errorRate = b.runs ? b.errors / b.runs : 0;
  const flags = [];
  if (active.get(id) && b.runs === 0) flags.push('never_ran_this_week');
  if (b.runs > 0 && errorRate > state.errorRateFlag) flags.push('error_rate');
  if (p50 !== null && prevP50 !== null && prevP50 > 0
      && p50 >= prevP50 * state.slowdownFactor && p50 - prevP50 >= state.slowdownMinMs) {
    flags.push('slowdown');
  }
  rows.push({
    id,
    name: names.get(id) || '(deleted workflow ' + id + ')',
    active: !!active.get(id),
    runs: b.runs,
    errors: b.errors,
    canceled: b.canceled,
    errorRate: Math.round(errorRate * 1000) / 1000,
    p50Ms: p50,
    maxMs: b.durations.length ? Math.max(...b.durations) : null,
    prevP50Ms: prevP50,
    // A workflow that did not succeed this week keeps last week's date, so "last success"
    // means the last one known, not the last one inside this window.
    lastSuccessAt: b.lastSuccessAt || (prev && prev.lastSuccessAt) || null,
    flags,
  });
}

// Worst first: most flags, then the highest error rate, then the name for a stable order.
rows.sort((a, b) => b.flags.length - a.flags.length || b.errorRate - a.errorRate || a.name.localeCompare(b.name));

const flagged = rows.filter((r) => r.flags.length);
const totals = {
  runs: rows.reduce((s, r) => s + r.runs, 0),
  errors: rows.reduce((s, r) => s + r.errors, 0),
  workflowsRan: rows.filter((r) => r.runs > 0).length,
  activeWorkflows: workflows.filter((w) => w.active).length,
  inactiveWorkflows: workflows.filter((w) => !w.active).length,
  flagged: flagged.length,
};

const stats = {};
for (const r of rows) {
  stats[r.id] = { name: r.name, runs: r.runs, errors: r.errors, p50Ms: r.p50Ms, maxMs: r.maxMs, lastSuccessAt: r.lastSuccessAt };
}

const schema = {
  type: 'object',
  required: ['summary_ru', 'top_issues'],
  properties: {
    summary_ru: { type: 'string' },
    top_issues: {
      type: 'array',
      items: {
        type: 'object',
        required: ['workflow', 'issue', 'suggested_check'],
        properties: {
          workflow: { type: 'string' },
          issue: { type: 'string' },
          suggested_check: { type: 'string' },
        },
      },
    },
  },
};

return [{
  json: {
    ...state,
    rows,
    flagged,
    totals,
    prevWeek,
    hasFlags: flagged.length > 0,
    truncated: { executions: executionsTruncated, workflows: listTruncated },
    snapshot: {
      week_start: state.weekStart,
      // Explicit, because an upsert keeps the old default on a re-run.
      taken_at: state.until,
      window_since: state.since,
      window_until: state.until,
      totals,
      stats,
    },
    // Only the flagged rows go to the model. It is asked to explain numbers, not to find
    // problems of its own, and it never sees a workflow it could invent an issue about.
    llmRequest: {
      model: state.model,
      max_retries: 1,
      schema,
      system: 'You review the weekly health numbers of an n8n instance for its owner. '
        + 'Only discuss the workflows you are given, by their exact names. Do not invent '
        + 'causes you cannot see in the numbers; say what to check instead. Write '
        + 'summary_ru in ' + state.language + ', at most three sentences. Keep each issue '
        + 'and suggested_check under 120 characters, also in ' + state.language + '.',
      user: JSON.stringify({
        window: { since: state.since, until: state.until },
        totals,
        flagged: flagged.map((r) => ({
          workflow: r.name, flags: r.flags, runs: r.runs, errors: r.errors,
          p50_ms: r.p50Ms, previous_p50_ms: r.prevP50Ms, last_success_at: r.lastSuccessAt,
        })),
      }),
    },
  },
}];

// Builds the Telegram message. The numbers are the report; the model's summary is an
// addition that can be missing without taking the report down with it.
const TELEGRAM_LIMIT = 4096;
const SAFETY = 96;
const state = $('Aggregate').first().json;

let summary = null;
let issues = [];
let droppedIssues = 0;
let summaryFailed = false;
if (state.hasFlags) {
  try {
    const r = $('Ask for a summary').first().json || {};
    if (r.ok && r.data) {
      summary = String(r.data.summary_ru || '').trim().slice(0, 700) || null;
      // Issues are kept only when they name a workflow that was actually flagged. A model
      // that invents a problem with a healthy workflow is worse than one that says nothing.
      const known = new Set(state.flagged.map((f) => f.name));
      for (const i of Array.isArray(r.data.top_issues) ? r.data.top_issues : []) {
        if (i && known.has(i.workflow)) issues.push(i);
        else droppedIssues += 1;
      }
    } else {
      summaryFailed = true;
    }
  } catch (e) {
    summaryFailed = true;
  }
}

const day = (iso) => DateTime.fromISO(iso).setZone(state.timezone).toFormat('d LLL');
const ms = (n) => (n === null || n === undefined ? '-' : n < 1000 ? n + 'ms' : (n / 1000).toFixed(1) + 's');
const pct = (x) => Math.round(x * 100) + '%';
const FLAG_TEXT = {
  never_ran_this_week: 'did not run',
  error_rate: 'high error rate',
  slowdown: 'slowed down',
};

const t = state.totals;
const head = [
  'n8n health, ' + day(state.since) + ' - ' + day(state.until),
  t.runs + ' runs, ' + t.errors + ' failed' + (t.runs ? ' (' + pct(t.errors / t.runs) + ')' : '')
    + '. ' + t.workflowsRan + ' of ' + t.activeWorkflows + ' active workflows ran.',
];
if (state.truncated.executions) head.push('Partial: more executions than the page cap, counts are a subset.');
if (state.truncated.workflows) head.push('Partial: more workflows than one page of the list.');
if (!state.prevWeek) head.push('No earlier snapshot, so no week-on-week comparison yet.');

const body = [];
if (!state.hasFlags) {
  body.push('', 'Nothing flagged.');
} else {
  if (summary) body.push('', summary);
  else if (summaryFailed) body.push('', 'Summary unavailable this week; the numbers below are complete.');
  body.push('', 'Flagged:');
  for (const r of state.flagged) {
    const parts = r.flags.map((f) => FLAG_TEXT[f] || f);
    const nums = r.runs
      ? r.runs + ' runs, ' + pct(r.errorRate) + ' failed, median ' + ms(r.p50Ms)
        + (r.flags.includes('slowdown') ? ' (was ' + ms(r.prevP50Ms) + ')' : '')
      : 'last success ' + (r.lastSuccessAt ? day(r.lastSuccessAt) : 'unknown');
    body.push('- ' + r.name + ': ' + parts.join(', ') + '. ' + nums);
  }
  if (issues.length) {
    body.push('', 'What to check:');
    for (const i of issues) body.push('- ' + i.workflow + ': ' + i.suggested_check);
  }
}
const tail = t.inactiveWorkflows ? ['', t.inactiveWorkflows + ' inactive workflows not checked.'] : [];

// One message, always. Lines are added until the next one would not fit, and what is left
// out is counted in the last line rather than silently dropped.
const budget = TELEGRAM_LIMIT - SAFETY;
const out = [...head];
let length = out.join('\n').length + tail.join('\n').length + 1;
let omitted = 0;
for (let i = 0; i < body.length; i++) {
  const extra = body[i].length + 1;
  if (length + extra > budget) { omitted = body.slice(i).filter((l) => l.startsWith('- ')).length; break; }
  out.push(body[i]);
  length += extra;
}
if (omitted) out.push('...and ' + omitted + ' more lines, see health_snapshots for the full week.');
out.push(...tail);
const message = out.join('\n');

return [{
  json: {
    chatId: state.chatId,
    snapshotUrl: state.snapshotUrl,
    snapshot: state.snapshot,
    message,
    messageLength: message.length,
    summaryUsed: !!summary,
    summaryFailed,
    droppedIssues,
    omitted,
  },
}];
